/* Ayar çerçevesi: solda bölüm listesi, sağda kendi içinde kayan form. Dar kolonda liste formun üstünde yatay şeride döner. */
.root { container-type: inline-size; display: grid; grid-template-columns: 15rem minmax(0, 1fr); height: 100%; min-height: 24rem; overflow: hidden; border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface); color: var(--foreground); font-family: var(--font-body); }
.side { display: flex; min-height: 0; flex-direction: column; gap: var(--space-4); border-right: 1px solid var(--border); padding: var(--space-5) var(--space-3) var(--space-3); background: var(--surface-muted); }
.title { margin: 0 var(--space-2); font-family: var(--font-display); font-size: var(--text-lg); font-weight: 600; letter-spacing: var(--tracking-display); }
.list { display: flex; flex: 1; flex-direction: column; gap: var(--space-1); overflow: auto; }
.tab { position: relative; display: flex; min-height: var(--control-height-md); align-items: center; gap: var(--space-3); border: 0; border-radius: var(--radius-control); padding: 0 var(--space-3); color: var(--text-secondary); background: transparent; font: inherit; font-size: var(--text-sm); text-align: left; cursor: pointer; transition: color var(--duration-fast) var(--ease-standard); }
.tab[aria-selected="true"] { color: var(--foreground); font-weight: 500; }
.tab:focus-visible { outline: var(--focus-outline-width) solid var(--focus-outline); outline-offset: var(--focus-outline-offset); }
.marker { position: absolute; inset: 0; z-index: 0; border-radius: var(--radius-control); background: var(--accent-subtle); }
.icon, .tabLabel, .dot { position: relative; z-index: 1; }
.icon { display: grid; place-items: center; }
.tabLabel { min-width: 0; flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dot { width: var(--space-2); height: var(--space-2); flex: none; border-radius: var(--radius-pill); background: var(--accent); }
@media (hover: hover) and (pointer: fine) { .tab:hover { color: var(--foreground); } }
.user { display: flex; align-items: center; gap: var(--space-3); border-top: 1px solid var(--border); padding: var(--space-3) var(--space-2) 0; }
.userCopy { display: grid; min-width: 0; }
.userName, .userSubtitle { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.userName { font-size: var(--text-sm); font-weight: 500; }
.userSubtitle { color: var(--text-muted); font-size: var(--text-xs); }
.scroller { position: relative; min-height: 0; overflow: auto; }
.form { max-width: 44rem; padding: var(--space-8) var(--space-8) var(--space-4); }
.panel { display: grid; gap: var(--space-6); animation: settings-fade var(--duration-standard) var(--ease-enter) both; }
.panel[hidden] { display: none; }
.head { display: grid; gap: var(--space-1); }
.sectionTitle { margin: 0; font-family: var(--font-display); font-size: var(--text-xl); font-weight: 600; letter-spacing: var(--tracking-display); }
.sectionDescription { margin: 0; color: var(--text-secondary); font-size: var(--text-sm); line-height: var(--leading-body); }
.fields { display: grid; gap: var(--space-5); min-width: 0; }
.group { display: grid; gap: var(--space-2); }
.groupTitle { margin: 0; color: var(--text-muted); font-size: var(--text-xs); font-weight: 500; }
.groupRows { display: grid; border: 1px solid var(--border); border-radius: var(--radius-surface); }
.row { display: flex; align-items: center; justify-content: space-between; gap: var(--space-5); padding: var(--space-4); }
.row + .row { border-top: 1px solid var(--border-subtle); }
.rowCopy { display: grid; min-width: 0; gap: var(--space-1); }
.rowTitle { font-size: var(--text-sm); font-weight: 500; }
.rowDescription { color: var(--text-secondary); font-size: var(--text-sm); line-height: var(--leading-body); }
.rowControl { flex: none; }
.srOnly { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
@keyframes settings-fade { from { opacity: 0; } to { opacity: 1; } }

/* Dar kolon (telefon, yan yana yerleşim): liste üstte yatay şerit, alanlar tek sütun. */
@container (max-width: 40rem) {
  .root { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
  .side { flex-direction: row; align-items: center; gap: var(--space-2); border-right: 0; border-bottom: 1px solid var(--border); padding: var(--space-2); }
  .title { display: none; }
  .list { flex-direction: row; overflow-x: auto; }
  .tab { flex: none; }
  .user { display: none; }
  .form { padding: var(--space-5) var(--space-4) var(--space-4); }
  .row { align-items: flex-start; flex-direction: column; gap: var(--space-3); }
}
@media (prefers-reduced-motion: reduce) { .panel { animation-duration: var(--duration-instant); } .tab { transition: none; } }

"use client";

import { useId, useRef, useState } from "react";
import type { KeyboardEvent, ReactNode } from "react";
import { motion, useReducedMotion } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import { Avatar } from "../avatar/avatar";
import { EmptyState } from "../empty-state/empty-state";
import { SaveBar } from "../save-bar/save-bar";
import type { SaveBarStatus } from "../save-bar/save-bar";
import { Skeleton } from "../skeleton/skeleton";
import styles from "./settings-page.module.css";

export interface SettingsSection {
  id: string;
  label: string;
  /** Bölüm listesinde adın yanındaki simge. Süstür; ekran okuyucu okumaz. */
  icon?: ReactNode;
  /** Bölüm başlığının altındaki bir cümlelik açıklama. */
  description?: string;
  /** Bu bölümde kaydedilmemiş kaç alan var. Sıfırdan büyükse satırda nokta çıkar; toplam, kaydetme çubuğuna gider. */
  changeCount?: number;
  /** Bölümün alanları. Boş bırakılırsa "boş durum" gösterilir. */
  content?: ReactNode;
}

export interface SettingsUser { name: string; subtitle?: string; src?: string }

export interface SettingsPageProps {
  sections: SettingsSection[];
  /** Seçili bölüm (denetimli kullanım). Verilmezse blok kendisi tutar. */
  value?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  /** Bölüm listesinin altındaki kullanıcı kartı. */
  user?: SettingsUser;
  /** Kaydetme çubuğu: gerçek kaydetmeyi proje yapar, blok yalnız durumu gösterir. */
  status?: SaveBarStatus;
  onSave: () => void;
  onDiscard: () => void;
  /** Form verisi gelirken true: alanlar yerine iskelet çıkar, kaydetme kapalıdır. */
  loading?: boolean;
  title?: string;
  /** Bölgenin erişilebilir adı. */
  label?: string;
  loadingLabel?: string;
  emptyTitle?: string;
  emptyDescription?: string;
  className?: string;
}

/** Bildirimler gibi bölümlerde satırları gruplayan başlıklı küme. */
export function SettingsGroup({ title, children }: { title: string; children: ReactNode }) {
  const id = useId();
  return <section className={styles.group} aria-labelledby={id}><h3 id={id} className={styles.groupTitle}>{title}</h3><div className={styles.groupRows}>{children}</div></section>;
}

/** Başlık, açıklama ve sağda bir denetim (çoğunlukla anahtar). */
export function SettingsRow({ title, description, children }: { title: string; description?: string; children: ReactNode }) {
  return <div className={styles.row}><div className={styles.rowCopy}><span className={styles.rowTitle}>{title}</span>{description && <span className={styles.rowDescription}>{description}</span>}</div><div className={styles.rowControl}>{children}</div></div>;
}

/** Solda bölüm listesi, sağda seçili bölümün formu, altta yüzen kaydetme çubuğu olan ayar çerçevesi.
 *  Bölümler arası geçişte yarım kalan değişiklikler kaybolmaz: bütün bölümler bağlı kalır, yalnız seçili olan görünür. */
export function SettingsPage({
  sections, value, defaultValue, onValueChange, user, status = "idle", onSave, onDiscard, loading = false,
  title = "Ayarlar", label = "Ayarlar", loadingLabel = "Ayarlar yükleniyor",
  emptyTitle = "Bu bölümde ayar yok", emptyDescription = "Burada gösterilecek bir tercih bulunmuyor.", className,
}: SettingsPageProps) {
  const uid = useId();
  const reduced = useReducedMotion();
  const [inner, setInner] = useState(defaultValue ?? sections[0]?.id ?? "");
  const active = value ?? inner;
  const tabs = useRef<Record<string, HTMLButtonElement | null>>({});
  const total = sections.reduce((sum, section) => sum + (section.changeCount ?? 0), 0);

  function select(id: string) {
    if (value === undefined) setInner(id);
    onValueChange?.(id);
  }

  // Ok tuşları bölüm değiştirir; odak tek satırdadır (roving tabindex), Tab formun içine geçer.
  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    const index = sections.findIndex(section => section.id === active);
    let next = -1;
    if (event.key === "ArrowDown" || event.key === "ArrowRight") next = (index + 1) % sections.length;
    else if (event.key === "ArrowUp" || event.key === "ArrowLeft") next = (index - 1 + sections.length) % sections.length;
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = sections.length - 1;
    const target = next >= 0 ? sections[next] : undefined;
    if (!target) return;
    event.preventDefault();
    select(target.id);
    tabs.current[target.id]?.focus();
  }

  return (
    <section className={[styles.root, className].filter(Boolean).join(" ")} aria-label={label}>
      <aside className={styles.side}>
        <h2 className={styles.title}>{title}</h2>
        <div className={styles.list} role="tablist" aria-orientation="vertical" aria-label={`${title} bölümleri`} onKeyDown={onKeyDown}>
          {sections.map(section => {
            const selected = section.id === active;
            const dirty = (section.changeCount ?? 0) > 0;
            return (
              <button
                key={section.id} ref={node => { tabs.current[section.id] = node; }} type="button" role="tab" id={`${uid}-tab-${section.id}`}
                aria-selected={selected} aria-controls={`${uid}-panel-${section.id}`} tabIndex={selected ? 0 : -1}
                className={styles.tab} onClick={() => select(section.id)}
              >
                {selected && <motion.span layoutId={`${uid}-marker`} className={styles.marker} transition={reduced ? { duration: 0 } : motionTokens.spring.smooth} aria-hidden="true" />}
                {section.icon && <span className={styles.icon} aria-hidden="true">{section.icon}</span>}
                <span className={styles.tabLabel}>{section.label}</span>
                {dirty && <><span className={styles.dot} aria-hidden="true" /><span className={styles.srOnly}>kaydedilmemiş değişiklik var</span></>}
              </button>
            );
          })}
        </div>
        {user && (
          <div className={styles.user}>
            <Avatar name={user.name} src={user.src} size="sm" />
            <span className={styles.userCopy}><span className={styles.userName}>{user.name}</span>{user.subtitle && <span className={styles.userSubtitle}>{user.subtitle}</span>}</span>
          </div>
        )}
      </aside>
      <div className={styles.scroller}>
        <div className={styles.form}>
          {sections.map(section => (
            <div
              key={section.id} id={`${uid}-panel-${section.id}`} role="tabpanel" aria-labelledby={`${uid}-tab-${section.id}`}
              hidden={section.id !== active} className={styles.panel} tabIndex={-1}
            >
              <header className={styles.head}>
                <h2 className={styles.sectionTitle}>{section.label}</h2>
                {section.description && <p className={styles.sectionDescription}>{section.description}</p>}
              </header>
              {loading ? <Skeleton label={loadingLabel} lines={4} />
                : section.content ? <div className={styles.fields}>{section.content}</div>
                : <EmptyState title={emptyTitle} description={emptyDescription} />}
            </div>
          ))}
        </div>
        <SaveBar changeCount={loading ? 0 : total} status={status} onSave={onSave} onDiscard={onDiscard} />
      </div>
    </section>
  );
}

export default SettingsPage;
